/* Authored Ukrainian explanations, shared by grammar pattern.
   Mnemonics are learning aids; sourced facts are kept separate below. */
(() => {
const lessons = {};
function lesson(pattern, why, remember) { lessons[pattern] = { why, remember }; }
lesson('on + day', 'Saturday — день тижня. Коли називаємо день події, перед ним ставимо on. In поєднуємо з місяцями й роками, а at — із точним часом.', 'День у календарі → on: on Monday, on Saturday.');
lesson('at + time', 'Коли відповідаємо на запитання «о котрій?», називаємо точку в часі: at 6. Noon — опівдні, теж точний момент, тому at noon.', 'Уявіть позначку на годиннику: at 6, at noon.');
lesson('in + month', 'Місяць — період, усередині якого відбувається подія. З назвою місяця без конкретного числа використовуємо in. Якщо додати число, потрібне on: on September 10.', 'Місяць → in September; дата → on September 10.');
lesson('in + year', 'Рік позначає тривалий період, тому подія відбувається in 2026. On потрібне з днем чи датою, а at — із точним часом.', 'Місяці й роки тримайте разом: in May, in 2026.');
lesson('in + part of day', 'Коли йдеться про ранок, день або вечір загалом, вживаємо in the morning / afternoon / evening. The входить у ці звичні сполучення. З конкретним днем буде on Monday morning.', 'Вранці загалом → in the morning; у понеділок вранці → on Monday morning.');
lesson('at night', 'Для ночі як звичного часу доби є усталене сполучення at night, без the. Його варто вчити окремо від in the morning. In the night теж можливе, коли йдеться про подію протягом певної ночі.', 'Вранці → in the morning. Уночі загалом → at night.');
lesson('on + date', 'September 10 — конкретний день у календарі, тому потрібне on. Коли є лише місяць, кажемо in September; число змінює вибір прийменника.', 'Побачили число й місяць разом → on.');
lesson('on the weekend', 'У цьому тренажері практикуємо американську англійську: on the weekend або on weekends. У першому сполученні потрібне the; варіант on weekend неповний.', 'American English: on the weekend / on weekends.');
lesson('in + season', 'Літо — пора року, тобто період, для якого використовуємо in. In summer та in the summer обидва можливі. At і on тут не передають потрібного значення.', 'Пора року → in: in summer, in winter.');
lesson('on + specific morning', 'Monday morning називає ранок конкретного дня. Тому використовуємо on, як і з Monday. In the morning означає вранці без уточнення дня.', 'Якщо є назва дня, орієнтуйтеся на неї: on Monday morning.');
lesson('no preposition + next', 'Next week уже означає «наступного тижня». Перед часовими виразами з next, last, this та every зазвичай не додаємо in, on чи at.', 'Next week, last year, every day — одразу після дії, без прийменника.');
lesson('for + duration', 'For відповідає на запитання «як довго?»: for two days. Since відповідає на інше запитання — «відколи?», тому після нього потрібна початкова точка, наприклад since Monday.', 'Скільки часу? → for. Відколи? → since.');
lesson('since + starting point', 'Since 2020 називає початок періоду, який триває до моменту, про який говоримо. Для тривалості потрібне for: for two years. Дія, що почалась раніше й триває досі, зазвичай має форму I have lived here since 2020.', 'Since + старт: since 2020. For + тривалість: for six years.');
lesson('by + deadline', 'By Friday встановлює крайній термін: надіслати можна раніше, але не пізніше п’ятниці. Until Friday означало б, що дія триває до п’ятниці, а не має бути завершена до неї.', 'By — дедлайн завершення; until — до якого моменту триває дія.');
lesson('until + end', 'Until 5 показує, що робота триває до п’ятої й на цій межі закінчується. At 5 називало б окремий момент, а by 5 — термін, до якого щось треба завершити.', 'Працюю до п’ятої → work until 5. Завершу до п’ятої → finish by 5.');
lesson('at home', 'At home — звичний спосіб сказати «вдома». Home тут означає власний дім як місце життя, тому the не додаємо. Для фізичного простору будинку можна сказати in the house.', 'Де? → at home. Куди? → go home.');
lesson('at work', 'At work описує, що людина на роботі або працює. Work тут означає діяльність, а не окрему злічувану будівлю, тому артикль не потрібен.', 'На роботі → at work; на роботу → to work.');
lesson('at school', 'At school у цій ситуації означає перебувати в школі як учень, на заняттях. School називає звичну діяльність, тому без the. Якщо говорити саме про будівлю, можна сказати in the school building.', 'Навчання → at school; усередині будівлі → in the school building.');
lesson('in the office', 'In підкреслює, що людина всередині офісу. The показує, що зрозуміло, про який офіс ідеться. At the office також правильно, коли важливе місце роботи, а не перебування всередині.', 'Усередині → in; відомий офіс → the office.');
lesson('in + enclosed place', 'In the house означає всередині конкретного будинку. Перед house в однині потрібне слово на зразок the, a або my. Keys — множина, тому з ним узгоджується are.', 'Ключі — їх кілька: the keys are. Усередині будинку: in the house.');
lesson('in the car', 'У салоні автомобіля кажемо in the car. On the car означало б на зовнішній поверхні, наприклад на даху. The вказує на конкретне авто, про яке говоримо.', 'Пасажир у салоні → in the car. Річ на даху → on the car.');
lesson('on + public transport', 'Коли людина їде пасажиром потяга чи автобуса, звично кажемо on the train / bus. Це усталений спосіб описати поїздку. Якщо називаємо лише спосіб пересування, використовуємо by train / bus.', 'Пасажир → on the train. Спосіб подорожі → by train.');
lesson('in + city', 'Місто розглядаємо як територію, у межах якої живемо, тому in Kyiv. At більше підходить для точки чи повної адреси, а on — для поверхні або вулиці.', 'У межах міста → in Kyiv, in Boston.');
lesson('at + meeting point', 'At the station задає станцію як точку, де слід чекати. The потрібне, бо мається на увазі зрозуміла співрозмовникам станція. Якщо важливо бути всередині будівлі, можливе in the station.', 'Точка зустрічі → at the station.');
lesson('on + surface', 'Телефон лежить на поверхні столу, тому on the table. In означало б усередині, а at — біля точки чи за столом; це інші просторові відношення.', 'На поверхні → on. Усередині → in.');
lesson('in + area', 'Центр міста тут — район, у межах якого відбудеться зустріч, тому in the city center. The входить у позначення центру конкретного міста.', 'У межах району → in the city center.');
lesson('at + address', 'Повна адреса з номером будинку задає точну точку: at 25 Main Street. Без номера, коли йдеться просто про вулицю, в американській англійській часто кажуть on Main Street.', 'Місто → in; вулиця → on; номер будинку й вулиця → at.');
lesson('on + floor', 'Для поверху в будинку використовуємо on. Порядковий числівник second визначає конкретний поверх, тому перед ним стоїть the.', 'На якому поверсі? → on the second floor.');
lesson('in + country', 'Країну розглядаємо як територію, у межах якої живе родина: in Ukraine. Перед назвою Ukraine артикля немає. At і on не використовуємо для цього значення.', 'Місто й країна → in Kyiv, in Ukraine.');
lesson('go home', 'Після go слово home саме передає напрямок «додому». Воно працює як прислівник напрямку, тому додаткове to не потрібне. Для перебування вдома використовується інша конструкція: at home.', 'Додому → go home; вдома → be at home.');
lesson('go to work', 'Go to work означає вирушати на роботу як на звичне заняття. To передає напрямок, а work у цьому сполученні не потребує the. Для конкретної офісної будівлі кажемо go to the office.', 'Запам’ятайте пару: go to work → be at work.');
lesson('go to the office', 'Go описує рух, тому до місця веде to. Office — злічуваний іменник в однині; the потрібне, бо йдеться про наш, відомий офіс.', 'Рух → to; знайомий офіс → the office.');
lesson('go to school', 'Go to school — ходити до школи на навчання. To передає напрямок, а school у значенні навчання вживається без артикля. At school описує, де людина вже перебуває.', 'Куди? → to school. Де? → at school.');
lesson('go to bed', 'Go to bed — усталене сполучення зі значенням «лягати спати». У ньому немає the. Go to the bed можливе, якщо людина підходить до конкретного ліжка як предмета.', 'До сну → go to bed; до предмета → go to the bed.');
lesson('go to the + destination', 'Коли go має назване місце призначення, зазвичай додаємо to. The store — конкретний або звичний магазин. At the store описує перебування там, а не рух туди.', 'Йду до магазину → go to the store; я там → at the store.');
lesson('get to', 'Get to a place означає дістатися до місця. У запитанні в Present Simple потрібне do: How do I get to the station? Після do дієслово get лишається у звичайній формі.', 'Як дістатися? → How do I get to …?');
lesson('arrive in', 'З arrive перед містом або країною вживаємо in: arrive in Athens. Для конкретної точки, наприклад готелю, зазвичай потрібне at. Прийменник to після arrive у цих конструкціях не використовуємо.', 'Arrive in + місто; arrive at + конкретне місце.');
lesson('arrive at', 'Готель тут — конкретне місце прибуття, тому arrive at the hotel. На відміну від go to, дієслово arrive в цій конструкції поєднується з at, а не to.', 'Go to the hotel → arrive at the hotel.');
lesson('leave for', 'Leave for New York означає вирушити до Нью-Йорка. For називає місце призначення. Leave New York без for означало б покинути Нью-Йорк — напрямок змінився б на протилежний.', 'Leave Kyiv — виїхати з Києва; leave for Kyiv — вирушити до Києва.');
lesson('a + singular noun', 'Один злічуваний предмет при першій згадці зазвичай потребує a або an. Тут наступне слово починається з приголосного звука, тому a: a car, a problem, a new website, a question.', 'Один із багатьох + приголосний звук → a.');
lesson('an + vowel sound', 'Один злічуваний предмет тут згадується як один із можливих. Перед голосним звуком використовуємо an: an apple, an office, an elevator. Вирішальне значення має звук наступного слова.', 'Промовте слово: початок голосний → an.');
lesson('the + known noun', 'Співрозмовник бачить, які саме двері треба зачинити, тому the door. The робить предмет визначеним. Door — злічуваний іменник в однині, тож просто Close door у звичайному реченні неповне.', 'Можна показати «ось ці» → the.');
lesson('no article + help', 'Help у значенні допомоги загалом — незлічуваний іменник. Тут ми не рахуємо одну допомогу, тому a/an не потрібні. Для конкретної допомоги, яку вже обговорили, можливе the help.', 'Потребую допомоги загалом → need help.');
lesson('no article + coffee', 'Coffee як напій загалом вживається без артикля. У цьому реченні йдеться про звичку, а не про замовлення однієї чашки. Після I потрібне drink, без -s.', 'Люблю напій → drink coffee. Замовляю чашку → a coffee.');
lesson('watch TV', 'Watch TV означає дивитися телепередачі; TV тут називає заняття, тому артикля немає. Коли говоримо про телевізор як предмет, можливе a TV. Після I використовуємо watch, без -es.', 'Заняття → watch TV; предмет → buy a TV.');
lesson('article before job', 'Web developer — злічувана назва професії. Коли кажемо, ким працює одна людина, потрібне a/an. Web починається з приголосного звука /w/, тому a web developer.', 'She is a developer. She is an engineer. Слухайте перший звук.');
lesson('an + silent h', 'У слові hour літера h не вимовляється. Перший звук голосний, тому перед hour потрібне an, хоча написання починається з приголосної літери.', 'Орієнтир — вимова: an hour, але a house.');
lesson('a + consonant sound', 'University починається зі звука /j/, приблизно українського «й». Це приголосний звук, тому a university. Вибір a/an залежить від вимови, а не від першої літери.', 'University звучить із «й» → a university.');
lesson('the + second mention', 'Спочатку телефон з’являється в розмові як новий предмет: a phone. У наступному реченні вже зрозуміло, який саме телефон чорний, тому the phone.', 'Перший раз: a phone. Той самий удруге: the phone.');
lesson('no article + plural general', 'Dogs у множині позначає собак загалом, тому артикль не потрібен. A/an вживають лише з одниною. Після I дієслово like не має закінчення -s.', 'Собаки загалом → dogs. Одна собака → a dog.');
lesson('wait for', 'Коли називаємо людину чи річ, на яку чекаємо, після wait потрібне for. Саме for пов’язує очікування з його об’єктом: wait for me, wait for a reply.', 'Вчіть два слова разом: wait for — чекати на.');
lesson('listen to', 'Коли уважно слухаємо музику чи людину, використовуємо listen to. Listen for теж існує, але означає прислухатися, очікуючи певний звук, наприклад дзвінок.', 'Слухаю те, що звучить → listen to; чекаю на звук → listen for.');
lesson('ask for', 'Ask for help означає попросити допомоги. For називає те, що хочемо отримати. Ask someone без for зазвичай означає запитати людину, наприклад ask a teacher.', 'Прошу щось → ask for something; питаю когось → ask someone.');
lesson('pay for', 'Коли оплачуємо товар або послугу, використовуємо pay for. Той, хто отримує гроші, може стояти одразу після pay: pay the driver. Квиток тут є покупкою, тому pay for the ticket.', 'За що плачу? → pay for. Кому плачу? → pay someone.');
lesson('talk to', 'Коли називаємо співрозмовника, використовуємо talk to або talk with. Після I дієслово talk не має -s. Сам іменник coworker не може одразу бути об’єктом talk у цьому значенні.', 'Talk to someone — розмовляти з кимось.');
lesson('look for', 'Look for означає шукати, тобто намагатися знайти. Look at — дивитися на те, що вже бачимо. Саме прийменник змінює значення конструкції.', 'Телефон зник → look for it. Телефон перед вами → look at it.');
lesson('think about', 'Think about the trip — міркувати про подорож. About називає тему думок. Think of the trip теж можливе залежно від контексту, але think for не передає це значення.', 'Тема думок → think about something.');
lesson('work on', 'Work on a project / website означає працювати над завданням чи результатом. On називає об’єкт роботи. Work for зазвичай називає роботодавця, а work in — сферу чи місце.', 'Над чим працюю? → work on. На кого? → work for.');
lesson('ready for', 'Ready — прикметник «готовий». Перед подією або іменником використовуємо for: ready for the meeting. Перед дією можлива інша конструкція: ready to start.', 'Ready for + подія; ready to + дія.');
lesson('interested in', 'Після interested перед темою інтересу використовуємо in. Усе сполучення be interested in означає «цікавитися чимось». Technology тут називає сферу загалом.', 'Вчіть як один блок: be interested in.');
lesson('good at', 'Good at позначає вміння або навичку. Після at може бути іменник або дія з -ing: good at programming. Good for має інше значення — корисний для когось чи чогось.', 'Добре вмію → good at. Корисно для → good for.');
lesson('afraid of', 'Перед тим, чого боїмося, використовуємо afraid of: spiders, heights. Перед дією можливе afraid to + дієслово, наприклад afraid to ask, але не afraid to spiders.', 'Afraid of + предмет страху; afraid to + дія, на яку не наважуємося.');
lesson('tired of', 'Tired of означає, що щось набридло. Of — прийменник, тому дія після нього має форму з -ing: tired of waiting. Це відрізняється від просто tired — фізично втомлений.', 'Втомився → tired. Набридло чекати → tired of waiting.');
lesson('belong to', 'Belong to me означає «належати мені». To пов’язує предмет із власником. Bag — однина, тому в ствердженні Present Simple дієслово має -s: belongs.', 'Що + belongs to + кому.');
lesson('depend on', 'Depend on означає «залежати від». Українське «від» тут не перекладаємо буквально як from або of: англійське дієслово має власне сполучення з on.', 'Вчіть пару depend on цілком, без окремого перекладу on.');
lesson('this introduces', 'This is допомагає показати або представити предмет чи людину. This — «це», а is поєднує його з назвою. It частіше продовжує розмову про вже названий предмет; its означає належність.', 'Показую вперше → This is my phone. Потім розповідаю → It is new.');
lesson('it refers back', 'It замінює вже названий телефон, щоб не повторювати a phone. В англійському реченні зі станом потрібні і підмет it, і дієслово is. Its — інша форма, що означає належність.', 'A phone → it. Його батарея → its battery.');
lesson("it's = it is", 'It’s — скорочення двох слів it is. Апостроф показує пропущені літери. Тому ще одне is після it’s зайве. Its без апострофа означає «його/її» і має стояти перед назвою предмета.', 'Розгорніть скорочення: It’s good → It is good.');
lesson('its = possession', 'Its стоїть перед іменником і показує належність: its battery — батарея цього пристрою. It’s розгортається в it is або it has, що тут не підходить. It саме по собі замінює предмет, але не означає «його».', 'Спробуйте підставити «його»: його батарея → its battery.');
lesson("it's = it has", 'Тут it’s скорочує it has, а не it is: It has been a long day → It’s been a long day. Has been — форма Present Perfect: мовець озирається на день до теперішнього моменту. Is been такої форми не утворює.', 'Після it’s бачите been → розгорніть у it has been.');
lesson('it in questions', 'It називає вже відомий пристрій. У запитанні Present Simple з it потрібне does, а після нього звичайна форма work. Its — форма належності, тому підметом тут не підходить.', 'It works → Does it work? Закінчення переходить у does.');
lesson('I am + state', 'Busy, tired, ready — прикметники, що описують стан. В англійській перед ними потрібне be, а з I його форма — am. Have означає «мати» і не поєднується з цими прикметниками як дієслово стану.', 'Який я зараз? → I am + стан. Що я маю? → I have + предмет.');
lesson('he/she is', 'Коли описуємо стан чи місце перебування he, she або it, потрібне is. Am поєднується з I, а are — з you, we, they. At home відповідає на запитання «де?».', 'I am · he/she/it is · you/we/they are.');
lesson('we/they are', 'Для стану з they, we або you використовуємо are. Ready та happy — прикметники, тому have перед ними не підходить. Am та is узгоджуються з іншими займенниками.', 'They are ready. We are happy. You are right.');
lesson('be question', 'Ready — стан, тому потрібне be. З you це are. У прямому запитанні are переходить перед підметом: You are ready → Are you ready? Допоміжне do тут не потрібне.', 'You are … → Are you …? Просто поміняйте порядок.');
lesson('be negative', 'Для заперечення стану ставимо not після be: he is not tired. Можна скоротити до isn’t. Does not потрібне зі звичайними дієсловами дії, а tired — прикметник.', 'He is tired → He is not tired.');
lesson('I/they have', 'Коли говоримо про наявність або володіння, потрібне have. З I, you, we та they використовується have; has — з he, she, it. Are a car означало б, що люди самі є машиною.', 'Вони мають → they have. Вони є → they are.');
lesson('he/she has', 'Have означає мати. У ствердженні Present Simple з he, she та it його форма — has. Is означає «є/перебуває», тому не передає наявність машини чи запланованої зустрічі.', 'I have, they have; але he has, she has.');
lesson('have vs be', 'Work to do — робота, яку треба виконати. Ми її маємо, тому I have work to do. Для стану «я зайнятий» була б інша конструкція: I am busy. З I використовуємо have, а не has.', 'Маю роботу → have work. Зайнятий → am busy.');
lesson('does + have', 'Запитання про наявність з he утворюємо за допомогою does. Він уже показує третю особу однини, тому основне дієслово повертається у форму have, без -s.', 'He has time → Does he have time?');
lesson('do not have', 'Для заперечення наявності в цій конструкції потрібне don’t have. З we використовуємо do, а не does. Are not описує стан або тотожність, але не заперечує володіння через have.', 'We have a car → We don’t have a car.');
lesson('do + you', 'Для запитання про звичну дію work у Present Simple потрібне do. З you використовуємо do, а з he/she/it — does. Are you працює з прикметником або формою -ing, але не з work у цій формі.', 'You work → Do you work?');
lesson('does + base verb', 'У запитанні Present Simple з he, she або it потрібне does. Він уже несе граматичне закінчення, тому після нього work, а не works. У ствердженні було б He works.', 'He works → Does he work? Лише один показник третьої особи.');
lesson('does not + base verb', 'Для заперечення з he потрібне doesn’t. Після нього дієслово має базову форму work, без -s: граматична форма вже виражена в does. On Sunday називає день.', 'He works → He doesn’t work.');
lesson('do not + verb', 'У Present Simple заперечення зі звичайним дієсловом та I утворюємо через don’t. Після нього go — без змін. Am not поєднуємо зі станом або формою -ing, а doesn’t — з he/she/it.', 'I go → I don’t go.');
lesson('question word + do', 'Where задає запитання про місце, а do допомагає утворити запитання зі звичайним дієсловом live. Порядок: Where + do + you + live? Are перед live у цій формі не потрібне.', 'Питальне слово → do/does → хто → дія.');
lesson('frequency before verb', 'У нейтральному реченні usually ставимо перед звичайним дієсловом: I usually drink coffee. Не розділяємо drink і його об’єкт coffee. З I форма drink не має -s.', 'Хто → як часто → що робить: I usually drink.');
lesson('frequency after be', 'З be прислівник частотності зазвичай стоїть після am/is/are: I am always busy. Busy — прикметник стану, а busily — прислівник способу дії, тому після am тут потрібне busy.', 'Звичайна дія: usually work. Стан: am usually busy.');
lesson('never without not', 'Never уже містить заперечення «ніколи». У стандартній англійській не додаємо до нього don’t для того самого заперечення. Після I використовуємо use, без -s.', 'I never use … = Я ніколи не користуюся …');
lesson('rarely', 'Rarely — прислівник «рідко», який описує частоту дії. Rare — прикметник «рідкісний», тому не замінює rarely перед watch. З I потрібне watch, без -es.', 'Рідкісна річ → rare. Рідко роблю → rarely.');
lesson('sometimes', 'Нейтрально ставимо sometimes перед звичайним дієсловом: I sometimes meet my friends. Також природно Sometimes I meet my friends або I meet my friends sometimes. Meet і my friends краще залишати разом.', 'Sometimes можна на початку, перед дією або в кінці; не розривайте дію й об’єкт.');
lesson('subject + verb + place', 'У звичайному ствердженні спочатку називаємо, хто діє, потім дію, а далі місце: I → work → at home. Український вільніший порядок слів не завжди можна перенести в англійську.', 'Хто? → що робить? → де?');
lesson('verb + object + time', 'Drink і його об’єкт coffee стоять поруч. Час можна додати наприкінці: I drink coffee in the morning. Можна винести час і на початок: In the morning I drink coffee.', 'Дія + що саме — разом; час — на початку або наприкінці.');
lesson('question word + should', 'У прямому запитанні should стоїть перед підметом we. Після we йде дієслово meet у базовій формі. What time разом означає «о котрій».', 'What time → should → we → meet?');
lesson('can + base verb', 'Can — модальне дієслово. Після нього потрібна базова форма meet, без to та без -s. Для часу зустрічі використовуємо at 7.', 'Can + дія без змін: can meet, can work, can go.');
lesson('want to + verb', 'Коли після want називаємо бажану дію, використовуємо to + базове дієслово: want to learn. Форма learning сама по собі цю конструкцію не замінює.', 'Хочу зробити → want to do.');
lesson('every day', 'Every day — готовий часовий вираз «щодня». Він не потребує on, in чи at. Go to work окремо означає йти чи їхати на роботу.', 'Every уже задає час: every day, every week — без прийменника.');
lesson('have breakfast', 'Have breakfast означає снідати: have тут описує прийом їжі. Перед breakfast у звичній назві трапези артикля немає. З I потрібне have, а годину називаємо через at.', 'Снідаю → have breakfast; о восьмій → at 8.');
lesson('get up at', 'Get up означає вставати з ліжка. Коли додаємо точну годину, використовуємо at: get up at 7. On використовуємо з днями, а in — з місяцями та частинами дня.', 'Встаю о котрій? → get up at …');
lesson('work as', 'As називає професійну роль: work as a web developer. Like означало б «працюю подібно до веброзробника», не обов’язково маючи цю професію. Перед злічуваною професією в однині потрібне a/an.', 'Ким працюю? → as. На кого схожий у дії? → like.');
lesson('have a meeting', 'Have a meeting означає мати заплановану зустріч або проводити її. Meeting — злічуваний іменник в однині, тому a потрібне. Am a meeting означало б «я є зустріччю».', 'Маю подію → have a meeting. Час події → at 3.');
lesson('send to', 'У конструкції send something to someone спочатку називаємо річ, потім отримувача через to. Send someone something також правильно: Send me the file.', 'Річ → to → отримувач: send the file to me.');
lesson('stay at a hotel', 'Be staying описує тимчасове проживання зараз. Перед назвою одного з готелів потрібне a: at a hotel. Staying in a hotel також можливе; at тут називає місце проживання.', 'Тимчасово живу → am staying; один із готелів → a hotel.');
lesson('on vacation', 'В американській англійській стан відпустки передаємо через on vacation. Vacation тут частина усталеного сполучення, тому артикля немає. In та at у цій конструкції не використовуємо.', 'Відпустка зараз → be on vacation.');
lesson('by + transport', 'By train називає спосіб пересування, тому після by тут немає артикля. On the train означає перебувати в конкретному потязі як пасажир. Це інший спосіб описати поїздку.', 'Як подорожую? → by train. Де я зараз? → on the train.');
lesson("let's + verb", 'Let’s виражає пропозицію зробити щось разом. Після нього потрібна базова форма meet, без to та -s. On Saturday додає день зустрічі.', 'Давайте зробимо → let’s + дія: let’s meet, let’s go.');
lesson('meet at', 'At задає кафе як точку зустрічі. The означає конкретне кафе, яке зрозуміле співрозмовникам. To передає рух до місця, але після meet для місця зустрічі тут потрібне at.', 'Зустрінемось де? → meet at the cafe.');
lesson('go to the movies', 'Go to the movies — звичний американський вираз «ходити в кіно». Він містить to як напрямок і the перед movies. Let’s робить його пропозицією піти разом.', 'Вчіть цілком: go to the movies — йти в кіно.');

// Key explanations by exact answer text so reordering options cannot change their meaning.
const reasons = {
  "ex-0001": {"in Saturday":"In використовуємо з періодами на зразок in September, а Saturday — день, тому on.","at Saturday":"At називає точний час, наприклад at 6; із Saturday потрібне on."},
  "ex-0003": {"on 6":"On поєднуємо з днями та датами. Шоста година — точний час, тому at 6.","in 6":"In не ставимо перед годиною. In six hours означало б «через шість годин»."},
  "ex-0005": {"on September":"On потрібне з конкретним днем: on September 10. Тут є лише місяць, тому in.","at September":"At не поєднується з назвою місяця в цьому значенні; місяць — in September."},
  "ex-0007": {"at 2026":"At задає точний час доби, а рік — період, тому in 2026.","on 2026":"On потрібне з днем чи датою, а не з роком без місяця й числа."},
  "ex-0009": {"at the morning":"З morning загалом використовуємо in the morning. At є в іншому усталеному виразі: at night.","on the morning":"On можливе з конкретним ранком, наприклад on Monday morning. Тут день не уточнено."},
  "ex-0011": {"in night":"In night без the не є звичним виразом. In the night можливе для події протягом певної ночі.","on night":"On можливе з уточненою ніччю, наприклад on Friday night; для ночі загалом потрібне at night."},
  "ex-0013": {"in September 10":"In September було б правильно для місяця, але число 10 робить це конкретним днем: on September 10.","at September 10":"At не використовуємо перед календарною датою; потрібне on."},
  "ex-0015": {"in the weekend":"Для значення «у вихідні» тут потрібне американське on the weekend. In the weekend не є цільовим усталеним виразом.","on weekend":"В однині в цьому сполученні потрібне the. Без артикля можна сказати on weekends, у множині."},
  "ex-0017": {"in noon":"Noon — точний момент, 12-та дня. Для нього використовуємо at, а не in.","on noon":"On поєднується з днем чи датою; noon — момент усередині дня."},
  "ex-0019": {"at summer":"Для пори року потрібне in summer або in the summer; at не передає цей період.","on summer":"On потрібне з днем: on a summer day. Саме літо — in summer."},
  "ex-0021": {"in Monday morning":"In the morning означає вранці загалом, але Monday morning називає конкретний день і потребує on.","at Monday morning":"At ставимо з годиною, а не з ранком названого дня."},
  "ex-0023": {"See you on next week.":"Next week уже задає час. Додаткове on перед цим виразом не потрібне.","See you in next week.":"Перед next week прийменника немає. In a week означало б «через тиждень» — це інша конструкція."},
  "ex-0025": {"since two days":"Since потребує початкової точки: since Monday. Two days — тривалість, тому for.","at two days":"At задає момент, але two days — кількість часу, на яку потрібне for."},
  "ex-0027": {"for 2020":"For називає тривалість, наприклад for six years. 2020 — початкова точка, тому since.","on 2020":"On використовуємо з датою чи днем. Для значення «з 2020 року» потрібне since."},
  "ex-0029": {"Send it until Friday.":"Until означає, що дія триває до п’ятниці. Для одноразового надсилання з крайнім терміном потрібне by.","Send it in Friday.":"З Friday як днем можливе on Friday — «у п’ятницю». Але «не пізніше п’ятниці» передає by Friday."},
  "ex-0031": {"I work on 5.":"On 5 не передає «до п’ятої». On використовуємо з днями, а тут потрібна кінцева межа until 5.","I work in 5.":"In 5 без одиниці часу неповне; in five hours означає «через п’ять годин», а не «до п’ятої»."},
  "ex-0033": {"I am in home.":"Для звичного «вдома» потрібне at home. Якщо підкреслюємо простір будинку, кажемо in the house.","I am at the home.":"The home може означати конкретний заклад чи дім у спеціальному контексті. Для «я вдома» the не потрібне."},
  "ex-0036": {"I am in work.":"In work може означати «мати роботу, бути працевлаштованим». Тут потрібно сказати, де я зараз: at work.","I am on work.":"On work не є виразом «на роботі». Українське «на» в цьому сполученні передаємо через at."},
  "ex-0039": {"She is on school.":"On зазвичай описує поверхню; для перебування в школі на заняттях потрібне at school.","She is in school building.":"School building — злічувана будівля в однині: потрібно in the school building. Варіант без the неповний."},
  "ex-0042": {"I am at office.":"Office в однині потребує означення: at the office. Без the цей варіант неповний.","I am in office building.":"Перед office building потрібне a або the: in the office building."},
  "ex-0045": {"The keys are in house.":"House — злічуваний іменник в однині. Для конкретного будинку потрібне in the house.","The keys is in the house.":"Keys — множина, тому are. Is поєднувалося б з одним ключем: The key is …"},
  "ex-0048": {"I am on the car.":"On the car означає на поверхні авто, наприклад на даху; пасажир перебуває in the car.","I am at car.":"Car в однині потребує означення. At the car означало б біля авто як точки, а не в його салоні."},
  "ex-0051": {"I am at train.":"Train в однині потребує означення; at the train до того ж не означає їхати пасажиром. Тут on the train.","I am on train.":"У значенні перебування пасажиром потрібне the: on the train. Без артикля є інша конструкція — by train."},
  "ex-0054": {"I live on Kyiv.":"On не описує проживання в межах міста. Для цього потрібне in Kyiv.","I live at Kyiv.":"At підходить для адреси чи точки, але для проживання в місті кажемо in Kyiv."},
  "ex-0057": {"Wait at station.":"У звичайному реченні перед station в однині потрібне the: at the station.","Wait on station.":"Station — місце зустрічі, тому at the station. До того ж у варіанті бракує the."},
  "ex-0059": {"The phone is in the table.":"In the table означало б усередині столу, а за умовою телефон лежить на поверхні.","The phone is at table.":"At the table описувало б перебування біля столу чи за ним. Тут потрібне on the table; також бракує the."},
  "ex-0061": {"on city center":"Для перебування в межах району потрібне in. Також city center у цій фразі потребує the.","at city center":"At the city center інколи можливе як точка, але тут ідеться про район. У запропонованому варіанті ще й бракує the."},
  "ex-0063": {"I live on 25 Main Street.":"On Main Street означає на вулиці загалом; із точним номером 25 використовуємо at.","I live in 25 Main Street.":"In використовуємо з містом чи країною. Повна адреса тут потребує at."},
  "ex-0065": {"in the second floor":"Для поверху використовуємо on the second floor; in означає усередині, а не номер поверху.","at second floor":"Для номера поверху потрібне on, а перед second floor — the."},
  "ex-0067": {"My family lives at Ukraine.":"At не описує проживання в межах країни. Потрібне in Ukraine.","My family lives on Ukraine.":"On використовуємо для поверхні, але країна як територія тут потребує in."},
  "ex-0069": {"We are at bus.":"У цьому варіанті бракує означення перед bus. Для пасажирів кажемо on the bus.","We is on the bus.":"З we потрібне are. Is використовується з he/she/it або одним предметом."},
  "ex-0071": {"I go to home.":"Home після go вже означає «додому», тому to зайве.","I go at home.":"At home означає «вдома» з be/stay. Для руху додому потрібно go home."},
  "ex-0073": {"I go to the work.":"The work може означати конкретну роботу чи твір. У значенні вирушати на роботу вживаємо go to work без the.","I go work.":"Перед work як місцем звичної діяльності потрібне to: go to work."},
  "ex-0076": {"I go office.":"Для руху до офісу потрібні to та означення перед office: go to the office.","I go to office.":"Office — злічуваний іменник в однині. Для нашого офісу потрібне the office."},
  "ex-0079": {"He goes school.":"У конструкції go to school потрібне to для напрямку. School без прийменника після goes тут не підходить.","He goes at school.":"At school описує місце перебування. Рух на навчання — goes to school."},
  "ex-0081": {"I go bed at 11.":"У виразі «лягати спати» потрібне to: go to bed.","I go to the bed at 11.":"Go to the bed означало б підійти до конкретного ліжка. Умова говорить про відхід до сну, тому без the."},
  "ex-0084": {"We go at the store.":"At the store описує перебування біля чи в магазині. Після go для напрямку потрібне to.","We go store.":"Перед store як місцем призначення потрібні to та означення: to the store."},
  "ex-0086": {"How do I get at the station?":"Конструкція «дістатися до» — get to, а не get at. Get at має інші значення, наприклад «мати на увазі».","How I get to the station?":"У прямому запитанні зі звичайним дієсловом потрібне do перед I: How do I get …?"},
  "ex-0088": {"We arrived to Athens.":"Після arrive з містом використовуємо in; go to не можна механічно переносити на arrive.","We arrived at Athens.":"Для міста як місця прибуття у звичайній розмові потрібно in Athens. At зазвичай ставимо з конкретною точкою."},
  "ex-0091": {"We arrived to the hotel.":"Arrive тут поєднується з at для конкретного місця. To використовувалося б у go to the hotel.","We arrived hotel.":"Між arrived і назвою готелю потрібен прийменник at."},
  "ex-0094": {"I leave at New York tomorrow.":"At може називати час відправлення: leave at 6. Для міста призначення потрібне for.","I leave to New York tomorrow.":"Місце, до якого вирушаємо, після leave вводимо через for, а не to."},
  "ex-0096": {"I have car.":"Car — один злічуваний предмет, тому тут потрібне a car.","I have an car.":"Car починається з приголосного звука /k/, тому a, а не an."},
  "ex-0099": {"I have problem.":"Problem — злічуваний іменник в однині, який тут потребує a.","I have an problem.":"Problem починається з приголосного /p/, тому a problem."},
  "ex-0102": {"I ate a apple.":"Apple починається з голосного звука, тому перед ним an.","I ate apple.":"Apple — один злічуваний предмет; без артикля чи іншого означення тут не обійтися."},
  "ex-0104": {"We rent a office.":"Office починається з голосного звука, тому потрібне an office.","We rent office.":"Office — злічуваний іменник в однині. Для одного з офісів потрібне an office."},
  "ex-0106": {"Close door.":"Door в однині потребує означення. Ми знаємо, які саме двері, тому the door.","Close an door.":"An не ставимо перед приголосним /d/. Крім того, йдеться про визначені двері, тому потрібне the."},
  "ex-0107": {"I need a help.":"Help у значенні допомоги загалом незлічуване, тому a тут не використовуємо.","I need an help.":"Help тут незлічуване й не потребує an. До того ж починається з приголосного /h/."},
  "ex-0109": {"I usually drink an coffee.":"Coffee починається з приголосного /k/, тому an не підходить. Напій загалом тут вживаємо без артикля.","I usually drinks coffee.":"З I потрібне drink. Drinks використовують у ствердженні з he/she/it."},
  "ex-0112": {"I watch an TV.":"TV вимовляється з початковим приголосним /t/, тож an не підходить. У виразі watch TV артикля взагалі немає.","I watches TV.":"Після I потрібне watch. Watches використовується з he/she/it."},
  "ex-0113": {"She is web developer.":"Назва професії в однині потребує a/an: a web developer.","She is an web developer.":"Web починається з приголосного /w/, тому a web developer, а не an."},
  "ex-0116": {"I have a hour.":"H у hour не вимовляється: перший звук голосний, тому an hour.","I have hour.":"Hour — злічуваний іменник в однині, тому тут потрібне an."},
  "ex-0119": {"This is an university.":"University починається зі звука /j/ («й»), який є приголосним. Тому a university.","This is university.":"University — один злічуваний заклад, тому потрібне a university."},
  "ex-0121": {"I bought a phone. Phone is black.":"Phone в однині не залишаємо без означення. Телефон уже згадали, тому the phone.","I bought a phone. An phone is black.":"An не підходить перед приголосним /f/. До того ж це вже відомий телефон, тому the."},
  "ex-0123": {"I like a dogs.":"A поєднується з одниною, а dogs — множина. Для собак загалом артикль не потрібен.","I likes dogs.":"Після I потрібне like. Likes — форма для he/she/it."},
  "ex-0125": {"We need new website.":"Website — злічуваний іменник в однині. Перед ним із прикметником потрібне a new website.","We need an new website.":"Артикль залежить від найближчого звука: new починається з приголосного /n/, тому a."},
  "ex-0127": {"There is a elevator.":"Elevator починається з голосного звука, тому an, а не a.","There is elevator.":"Elevator — злічуваний предмет в однині, який тут потребує an."},
  "ex-0129": {"Wait me.":"Коли називаємо того, на кого чекаємо, після wait потрібне for.","Wait to me.":"To позначає напрямок у багатьох конструкціях, але wait у цьому значенні потребує for."},
  "ex-0131": {"I listen music.":"Перед об’єктом слухання після listen потрібне to. Без нього music тут не приєднується.","I listen for music.":"Listen for music — прислухатися, очікуючи почути музику. Умова каже, що ви вже слухаєте її, тому to."},
  "ex-0134": {"Ask help.":"Прохання надати допомогу передаємо через ask for help. У звичайному сучасному мовленні for тут потрібне.","Ask of help.":"Of не називає бажану річ після ask у цій конструкції; потрібно for help."},
  "ex-0136": {"I pay to the ticket.":"To може називати отримувача платежу, але ticket — покупка, за яку платимо: for the ticket.","I pay of the ticket.":"Of не використовується для предмета оплати після pay. Потрібне pay for."},
  "ex-0138": {"I talk my coworker.":"Перед співрозмовником потрібне to або with: talk to my coworker.","I talks to my coworker.":"З I дієслово talk не має -s; talks — форма для he/she/it."},
  "ex-0140": {"I am looking my phone.":"Для значення пошуку після looking потрібне for.","I am looking to my phone.":"Look to має інші значення, наприклад покладатися на когось. Для пошуку загубленого телефона потрібно look for."},
  "ex-0143": {"I am thinking the trip.":"Для теми роздумів після thinking потрібне about або of; сам trip тут так не приєднується.","I am thinking for the trip.":"For не вводить тему думок. Тут потрібне thinking about the trip."},
  "ex-0145": {"I am working a website.":"Працювати над сайтом — work on a website. Без on цей варіант не передає потрібної конструкції.","I am working to a website.":"To не приєднує проєкт до work. Для об’єкта роботи потрібне on."},
  "ex-0148": {"I am ready the meeting.":"Перед подією після ready потрібне for: ready for the meeting.","I am ready of the meeting.":"Of не використовується після ready для події. Потрібне for."},
  "ex-0150": {"I am interested on technology.":"Interested поєднується з in, а не on, коли називаємо тему інтересу.","I am interested for technology.":"For не вводить тему після interested. Потрібне interested in technology."},
  "ex-0152": {"I am good in programming.":"Для навички використовуємо good at programming. Good in можливе в інших контекстах, але тут цільова конструкція — at.","I am good for programming.":"Good for programming означало б «корисний/придатний для програмування», а не «добре програмую»."},
  "ex-0154": {"She is afraid spiders.":"Перед предметом страху після afraid потрібне of: afraid of spiders.","She is afraid to spiders.":"Afraid to можливе перед дієсловом, наприклад afraid to ask. Spiders — іменник, тому of."},
  "ex-0156": {"I am tired to waiting.":"To waiting не утворює тут потрібної конструкції. Для «набридло чекати» потрібно tired of waiting.","I am tired for waiting.":"For не передає значення «набридло» після tired. Цю конструкцію утворює of."},
  "ex-0158": {"This bag belongs me.":"Власника після belong вводимо через to: belongs to me.","This bag belongs for me.":"For означало б інший зв’язок, наприклад призначення, але belong для власника потребує to."},
  "ex-0160": {"It depends of the weather.":"Українське «від» не перекладаємо тут через of. Усталена англійська конструкція — depend on.","It depends from the weather.":"From часто означає «звідки», але після depend у цьому значенні потрібне on."},
  "ex-0162": {"This my phone.":"В англійському реченні між this і my phone потрібне is: This is my phone.","Its is my phone.":"Its означає належність і стоїть перед іменником, наприклад its screen. Для показу предмета потрібно This is."},
  "ex-0165": {"I have a phone. Its is new.":"Its означає «його/її» перед іменником. Для заміни слова phone у ролі підмета потрібне it.","I have a phone. Is new.":"У цьому реченні пропущений підмет. Англійською потрібно It is new."},
  "ex-0167": {"Its good.":"Its без апострофа не означає it is. Для скорочення потрібне it’s.","It's is good.":"It’s уже містить is: розгортання дає It is is good. Друге is зайве."},
  "ex-0169": {"It's battery is dead.":"It’s = it is / it has. Жоден варіант не передає «батарея цього телефона»; потрібне присвійне its.","It battery is dead.":"It називає сам предмет. Щоб сказати, чия батарея, потрібне its battery."},
  "ex-0172": {"It's engine is good.":"It’s engine розгорталося б у it is engine або it has engine. Для належності двигуна потрібне its engine.","It engine is good.":"It саме по собі не означає «його». Перед engine потрібна форма належності its."},
  "ex-0174": {"Its raining.":"Для «дощить» потрібне it is raining, скорочено it’s raining. Its не є скороченням.","It's is raining.":"It’s уже означає it is. Додаткове is повторює дієслово двічі."},
  "ex-0176": {"Its been a long day.":"Its без апострофа означає належність: its battery. Тут треба скоротити it has, тому потрібне it’s.","It's has been a long day.":"It’s тут уже містить has. Після розгортання вийшло б It has has been — одне has зайве."},
  "ex-0178": {"Its my friend.":"Its — належність, а не скорочення it is. Для знайомства з людиною природно This is my friend.","This my friend is.":"Для представлення порядок — This is my friend. Is потрібно перед my friend, а не після."},
  "ex-0181": {"Does its work?":"Its передає належність, а не замінює сам пристрій у ролі підмета. Потрібне it.","Do it work?":"З it у запитанні Present Simple потрібне does, а не do."},
  "ex-0183": {"The restaurant is famous for it's pizza.":"It’s розгортається в it is / it has, але перед pizza потрібна належність: its pizza.","The restaurant is famous for it pizza.":"It не передає належність. Для «своєю піцою» ресторану потрібно its pizza."},
  "ex-0185": {"I have busy.":"Busy — прикметник стану. Потрібне am busy; have використовуємо з тим, що маємо.","I is busy.":"З I форма be — am. Is поєднується з he/she/it."},
  "ex-0187": {"She are at home.":"З she потрібне is. Are використовуємо з you/we/they.","She am at home.":"Am використовуємо лише з I. З she потрібне is."},
  "ex-0189": {"They have happy.":"Happy — стан, тому потрібне are happy. Have означає «мати» і не утворює тут опис стану.","They is happy.":"З they потрібне are. Is використовується з одниною he/she/it."},
  "ex-0191": {"Do you ready?":"Ready — прикметник стану, тому запитання утворює are, а не do.","You ready?":"You ready? трапляється в дуже неформальній розмові зі скороченням. У повному стандартному запитанні потрібне Are you ready?"},
  "ex-0193": {"He does not tired.":"Tired — прикметник. Для заперечення стану потрібне is not, а does not — зі звичайним дієсловом.","He not is tired.":"Not ставимо після is: He is not tired, а не перед is."},
  "ex-0196": {"They are a car.":"Are a car означало б «вони є машиною». Наявність передає have.","They has a car.":"Has використовується з he/she/it. З they потрібне have."},
  "ex-0199": {"She have a meeting.":"У ствердженні з she форма have — has.","She is a meeting.":"Is a meeting означало б, що вона сама є зустріччю. Наявність події передає has."},
  "ex-0202": {"I am work to do.":"Am work не передає наявність роботи. Потрібне have work; стан зайнятості — am busy.","I has work to do.":"З I використовуємо have. Has поєднується з he/she/it."},
  "ex-0204": {"Does he has time?":"Does уже показує третю особу. Після нього потрібно have, без повторного -s.","Is he have time?":"Наявність через have у цьому запитанні оформлюємо за допомогою does, а не is."},
  "ex-0207": {"We aren't have a car.":"Aren’t — заперечення be. Щоб заперечити have в цій конструкції, потрібно don’t have.","We doesn't have a car.":"З we потрібно don’t. Doesn’t використовуємо з he/she/it."},
  "ex-0209": {"Are you work?":"Після are могла б бути форма working: Are you working? Для work у Present Simple потрібне do.","Does you work?":"З you у Present Simple використовуємо do, а не does."},
  "ex-0211": {"Does he works?":"Does уже несе показник третьої особи, тому work має бути без -s.","Do he work?":"З he потрібне does. Do поєднується з I/you/we/they."},
  "ex-0213": {"He doesn't works on Sunday.":"Після doesn’t потрібна базова форма work. Works повторює граматичне закінчення.","He don't work on Sunday.":"З he заперечення утворюємо через doesn’t, а не don’t."},
  "ex-0215": {"I am not go out very often.":"Am not могло б поєднуватися з going. Для go у Present Simple потрібне don’t.","I doesn't go out very often.":"Doesn’t поєднується з he/she/it. З I потрібне don’t."},
  "ex-0217": {"Where you live?":"У повному прямому запитанні Present Simple потрібне do: Where do you live?","Where are you live?":"Are не поєднується з live у цій формі. Потрібне do; форма are living була б іншою конструкцією."},
  "ex-0220": {"I drink usually coffee.":"У нейтральному порядку usually ставимо перед drink, не між drink і його об’єктом coffee.","I usually drinks coffee.":"З I потрібне drink. Drinks використовуємо з he/she/it."},
  "ex-0223": {"I have always busy.":"Busy описує стан, тому потрібне am. Have не утворює конструкції have busy.","I am always busily.":"Busily — прислівник «заклопотано», наприклад work busily. Для стану після am потрібен прикметник busy."},
  "ex-0226": {"I don't never use social media.":"Never уже заперечує дію. У стандартній англійській don’t перед never для того самого заперечення зайве.","I never uses social media.":"З I використовуємо use. Uses — форма для he/she/it."},
  "ex-0229": {"I rare watch TV.":"Rare — прикметник «рідкісний». Частоту дії передає прислівник rarely.","I rarely watches TV.":"Після I потрібне watch. Watches використовується з he/she/it."},
  "ex-0232": {"I meet sometimes my friends.":"У нейтральному реченні не розриваємо meet my friends. Природніше I sometimes meet my friends або I meet my friends sometimes.","I sometimes meets my friends.":"З I потрібне meet. Meets використовуємо з he/she/it."},
  "ex-0234": {"I at home work.":"Для нейтрального речення ставимо дію після підмета: I work at home. Місце не вставляємо між I та work.","Work I at home.":"У звичайному ствердженні підмет I стоїть перед work. Work I … не є таким порядком."},
  "ex-0237": {"I drink in the morning coffee.":"Drink coffee тримаємо разом; час in the morning переносимо в кінець або на початок речення.","Drink I coffee in the morning.":"Ствердження починаємо з підмета I, потім drink. Інверсія Drink I тут не потрібна."},
  "ex-0239": {"What time we should meet?":"Це порядок для частини непрямого запитання, наприклад Tell me what time we should meet. У прямому should стоїть перед we.","What time should meet we?":"Після should має бути підмет we, а вже потім meet: should we meet."},
  "ex-0241": {"We can to meet at 7.":"Після can потрібне дієслово без to: can meet.","We can meets at 7.":"Після can дієслово не отримує -s, незалежно від підмета: can meet."},
  "ex-0244": {"I want learn English.":"Коли після want називаємо дію, потрібне to: want to learn.","I want learning English.":"У цій конструкції want потребує to learn. Саме learning після want не замінює інфінітив."},
  "ex-0247": {"I go to work on every day.":"Every day уже означає «щодня», тому on перед ним не додаємо.","I go to work in every day.":"Перед every day прийменник in не потрібен."},
  "ex-0249": {"I am breakfast at 8.":"Am breakfast означало б «я є сніданком». Для прийому їжі потрібне have breakfast.","I has breakfast at 8.":"З I використовуємо have. Has — форма для he/she/it."},
  "ex-0252": {"I get up on 7.":"On використовуємо з днем, а 7 — точна година, тому at 7.","I get up in 7.":"In 7 без одиниці часу неповне. Для «о сьомій» потрібне at 7."},
  "ex-0255": {"I work like a web developer.":"Like a web developer означає працювати подібно до розробника. Щоб назвати власну професію, потрібне as.","I work as web developer.":"Web developer — злічувана назва професії в однині, тому потрібне a web developer."},
  "ex-0258": {"I am a meeting at 3.":"Am a meeting означало б «я є зустріччю». Щоб сказати, що зустріч запланована, використовуємо have.","I have meeting at 3.":"Meeting в однині потребує означення: have a meeting."},
  "ex-0261": {"Send the file for to me.":"For to не використовуємо для отримувача в цій конструкції. Потрібне одне to: to me.","Send the file at me.":"At може вказувати на ціль спрямованої дії, але звичайного отримувача файла вводимо через to."},
  "ex-0263": {"I am staying at hotel.":"Hotel — злічуваний іменник в однині, тому перед ним потрібне a або the. Тут — a hotel.","I am stay at a hotel.":"Після am для тривалої дії потрібна форма staying. Am stay не утворює граматичної конструкції."},
  "ex-0265": {"I am in vacation.":"Для стану відпустки в американській англійській потрібне on vacation, а не in vacation.","I am at vacation.":"At називає точку чи місце, але для відпустки як стану потрібне on vacation."},
  "ex-0268": {"I travel by the train.":"Коли by називає спосіб пересування, артикль пропускаємо: by train. By the train може означати біля потяга, але це інший зміст.","I travel on train.":"Для перебування пасажиром потрібне on the train. Для способу пересування — by train."},
  "ex-0270": {"Let's to meet on Saturday.":"Після let’s дієслово ставимо без to: let’s meet.","Let's meets on Saturday.":"Після let’s потрібна базова форма meet. Закінчення -s не додаємо."},
  "ex-0273": {"Let's meet at cafe.":"Cafe — злічуване місце в однині, тому потрібне the cafe або a cafe. Тут знайоме кафе: the.","Let's meet to the cafe.":"To передає напрямок руху, але точку зустрічі після meet вводимо через at."},
  "ex-0275": {"Let's go movies.":"Вираз «іти в кіно» — go to the movies. У варіанті пропущено to the.","Let's go at the movies.":"Після go для напрямку потрібне to. Усталений вираз — to the movies."},
  "ex-0278": {"in":"In використовуємо з місяцями чи роками, а Saturday — день: on Saturday.","at":"At потрібне з точним часом, але з днем Saturday використовуємо on."},
  "ex-0280": {"on":"On називає день чи дату. Для шостої години потрібне at.","in":"In six hours означало б «через шість годин». Тут точний час початку: at 6."},
  "ex-0282": {"at":"At не використовуємо з місяцем у значенні часу події. Потрібне in September.","on":"On потрібне з днем чи датою, наприклад on September 10, але тут лише місяць."},
  "ex-0284": {"in":"Для «вдома» використовуємо at home. In можливе в іншій конструкції: in the house.","on":"On не входить до виразу «вдома». Потрібне at home."},
  "ex-0286": {"at":"At work означає перебувати на роботі. Після go для руху потрібне to work.","for":"For не утворює тут вираз руху на роботу. Потрібне go to work."},
  "ex-0288": {"a":"Office починається з голосного звука, тому an, а не a.","—":"Office — злічуваний іменник в однині, тому тут не можна залишити його без артикля."},
  "ex-0290": {"an":"Question починається з приголосного звука /k/, тому a, а не an.","—":"Question — один злічуваний іменник. Тут потрібне a question."},
  "ex-0292": {"a":"Help у значенні допомоги загалом незлічуване, тому a не потрібне.","an":"Help тут незлічуване й не потребує an. Його початковий /h/ до того ж приголосний."},
  "ex-0294": {"to":"Перед тим, на кого чекаємо, wait потребує for, а не to.","of":"Of не приєднує об’єкт очікування до wait. Потрібне for me."},
  "ex-0296": {"for":"Listen for означає прислухатися, очікуючи звук. Тут слухаємо музику, тому listen to.","at":"At поєднується з look для погляду: look at. Для слухання потрібне listen to."},
  "ex-0298": {"to":"Afraid to ставимо перед дією, наприклад afraid to jump. Heights — іменник, тому of.","at":"At не вводить предмет страху після afraid. Потрібне afraid of heights."},
  "ex-0300": {"to":"To не вводить проєкт після work. Працювати над проєктом — work on a project.","of":"Of не використовується для об’єкта роботи в цій конструкції. Потрібне on."},
  "ex-0302": {"Do":"З he у Present Simple використовуємо does, а не do.","Is":"Is могло б бути з working: Is he working here? З work потрібне does."},
  "ex-0304": {"have":"У ствердженні з she потрібна форма has, а не have.","is":"Is означало б, що вона сама є машиною. Наявність машини передає has."},
  "ex-0306": {"am":"Am поєднується з I. З they потрібне are.","is":"Is використовуємо з he/she/it. З they потрібне are."},
  "ex-0308": {"I":"I — правильний підмет «я». Помилка в зайвому the перед work.","go":"Go правильно узгоджене з I. Треба прибрати the, а не змінювати go.","to":"To потрібне для напрямку на роботу. Зайвим є the після нього.","work":"Work правильно називає роботу як заняття. Треба прибрати the перед ним.","every":"Every правильно входить до every day — «щодня». Помилка в the work.","day":"Day правильно завершує every day. Треба прибрати the перед work."},
  "ex-0309": {"Does":"Does правильно утворює запитання з he. Помилка в works: після does потрібне work.","he":"He — правильний підмет. Змінюємо works на work після does.","here":"Here правильно означає «тут». Помилка — зайве -s у works."},
  "ex-0310": {"battery":"Battery правильно називає батарею. Належність перед нею має бути its без апострофа.","is":"Is правильно узгоджене з battery в однині. Помилка в початковому it’s, яке слід замінити на its.","dead":"Dead тут правильно означає розряджену батарею. Помилка в it’s замість its."},
  "ex-0311": {"I":"I — правильний підмет. Для стану потрібно змінити have на am.","tired":"Tired — правильний прикметник «втомлений». Змінюємо have на am, щоб описати стан."},
  "ex-0312": {"We":"We — правильний підмет. Помилка в in: перед Saturday потрібне on.","meet":"Meet правильно узгоджене з we. Треба змінити in на on.","Saturday":"Saturday — правильна назва дня. Помилка в прийменнику in перед ним."},
  "ex-0313": {"I go to the office.":"Це граматично правильне речення про рух до офісної будівлі. Умова просить назвати роботу як заняття, тому точніше go to work."},
  "ex-0314": {"It is old.":"Це граматично правильний опис віку вже відомого предмета: «Він старий». Він не представляє телефон; для цього потрібно This is my phone."},
  "ex-0315": {"I am on the car.":"Це граматично можливе речення про перебування на поверхні автомобіля. Для людини в салоні потрібно in the car."}
};

const sources = {
  time: ['Cambridge · прийменники часу', 'https://dictionary.cambridge.org/grammar/british-grammar/at-on-in-time'],
  place: ['Cambridge · прийменники місця', 'https://dictionary.cambridge.org/grammar/british-grammar/at-on-and-in-place'],
  articles: ['Cambridge · a/an і the', 'https://dictionary.cambridge.org/grammar/british-grammar/a-an'],
  its: ['Cambridge · it’s та its', 'https://dictionary.cambridge.org/grammar/british-grammar/its-or-its'],
  home: ['Cambridge · home після дієслів руху', 'https://dictionary.cambridge.org/grammar/british-grammar/prepositions-home'],
  coffee: ['British Council · злічувані й незлічувані іменники', 'https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/countable'],
  lets: ['Cambridge · let та let’s', 'https://dictionary.cambridge.org/grammar/british-grammar/let-let-'],
  breakfast: ['BBC Learning English · походження breakfast', 'https://downloads.bbc.co.uk/learningenglish/features/tae/bbc_tae_breakfast.pdf']
};
function fact(patterns, text, source) {
  for (const pattern of patterns) lessons[pattern].fact = { text, source: sources[source] };
}
fact(['on the weekend'], 'Американці зазвичай кажуть on the weekend, а британці — at the weekend. Відмінність пов’язана з варіантом англійської, тому at the weekend теж правильно.', 'time');
fact(['at night'], 'At night описує ніч як час доби загалом. In the night часто стосується чогось, що сталося протягом певної ночі. Тому in не завжди помилка — важлива вся фраза.', 'time');
fact(['an + silent h', 'a + consonant sound', 'an + vowel sound'], 'Літери можуть вводити в оману: an hour, бо h не звучить, але a university, бо перший звук — /j/. Артикль підлаштовується під вимову наступного слова.', 'articles');
fact(["it's = it is", "it's = it has", 'its = possession'], 'Одна форма it’s може приховувати два різні слова: is або has. Розгорніть скорочення й перевірте зміст. Its без апострофа — окрема форма належності, подібна до my або your.', 'its');
fact(['go home'], 'Home після go чи come може саме означати напрямок «додому». Тому без to працює не лише go home, а й come home та get home.', 'home');
fact(['on + public transport', 'by + transport'], 'By train відповідає на запитання «як подорожували?», а on the train — «де перебували?». Тому зміна прийменника також змінює артикль: by train, але on the train.', 'place');
fact(['no article + coffee'], 'Coffee може бути й злічуваним: a coffee в кафе означає одну порцію. Без артикля coffee називає сам напій. Тому артикль іноді змінює значення, а не просто виправляє граматику.', 'coffee');
fact(["let's + verb"], 'Let’s — скорочення let us. Воно зазвичай включає і мовця, і співрозмовника: це запрошення зробити щось разом.', 'lets');
fact(['have breakfast'], 'Слово breakfast походить від break + fast: «перервати піст», тобто період без їжі протягом ночі. Тут fast означає утримання від їжі, а не «швидкий».', 'breakfast');

for (const q of window.EXERCISES) {
  if (!lessons[q.pattern]) throw new Error(`Missing lesson: ${q.pattern}`);
  q.learning = lessons[q.pattern];
  if (q.options) {
    const wrong = q.options.filter(option => option !== q.correctAnswer);
    if (!reasons[q.id] || Object.keys(reasons[q.id]).length !== wrong.length || wrong.some(option => !reasons[q.id][option])) throw new Error(`Missing option explanation: ${q.id}`);
    q.wrongExplanations = reasons[q.id];
  }
}

// Pure HTML renderer: shared by hints and feedback, with escaping at the boundary.
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(q, { answer, hint = false } = {}) {
  const content = q.learning;
  if (!content) return `<p>${escape(q.explanationUk)}</p>`;
  const wrongs = q.options?.filter(option => option !== q.correctAnswer) || [];
  // Put the chosen alternative first without relying on shuffled button indices.
  wrongs.sort((a, b) => Number(b === answer) - Number(a === answer));
  const fact = content.fact;
  return `<section class="learning-section"><h3>Чому саме так</h3><p>${escape(content.why)}</p></section>
    ${!hint && wrongs.length ? `<section class="learning-section"><h3>${q.type === 'mistake' ? 'Чому інші слова не є помилкою' : 'Чому інші варіанти не підходять тут'}</h3><ul class="option-reasons">${wrongs.map(option => `<li${option === answer ? ' class="chosen-reason"' : ''}><b lang="en">${escape(option)}</b>${option === answer ? '<span class="choice-label">Ваш вибір</span>' : ''}<p>${escape(q.wrongExplanations[option])}</p></li>`).join('')}</ul></section>` : ''}
    <section class="learning-section memory-note"><h3>Як запам’ятати</h3><p>${escape(content.remember)}</p></section>
    <section class="learning-section"><h3>Приклади</h3><div class="examples">${q.examples.map(example => `<span lang="en">${escape(example)}</span>`).join('')}</div></section>
    ${fact ? `<details class="learning-fact"><summary>Цікава деталь${q.pattern === 'have breakfast' ? ' · походження слова' : ''}</summary><p>${escape(fact.text)}</p><a href="${escape(fact.source[1])}" target="_blank" rel="noopener noreferrer">${escape(fact.source[0])} ↗</a></details>` : ''}`;
}
function solution(q) {
  if (q.correctSentence) return q.correctSentence;
  if (q.type === 'multiple-choice') return q.question.replace('___', q.correctAnswer === '—' ? '' : q.correctAnswer).replace(/ {2,}/g, ' ');
  return q.correctAnswer;
}
window.PhraseLearning = { render, solution };
})();
